document.addEventListener('DOMContentLoaded', () => {
  const section = document.querySelector('.section-traffic')
  if (section) {
    const itemList = section.querySelectorAll('.section-traffic__item')
    itemList.forEach((item) => {
      const soundAnimation = item.querySelector('.section-traffic__sound-icon')
      const soundBox = item.querySelector('.section-traffic__sound-box')
      const sound = new Audio(item.dataset.sound)
      sound.loop = true
      if (soundAnimation) {
        const animation = lottie.loadAnimation({
          container: soundAnimation,
          renderer: 'svg',
          loop: true,
          autoplay: false,
          path: 'images/section-traffic/sound-animation.json'
        })

        soundBox.addEventListener('click', () => sound.play())

        item.addEventListener('mouseenter', () => {
          animation.play()
        })
        item.addEventListener('mouseleave', () => {
          animation.stop()
          sound.pause()
          sound.currentTime = 0
        })
      }
    })

    let mm = gsap.matchMedia()
    mm.add("(max-width: 1023px)", () => {
      const content = document.querySelector('.section-traffic__content')
      const cards = gsap.utils.toArray(".section-traffic__item");
      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: content,
          start: "top 100px",
          end: `+=${content.offsetHeight}`,
          scrub: 2,
          markers: false,
          pin: true,
          pinSpacer: false
        },
      })

      tl.to(cards[0], { scale: 0.8, opacity: .8, duration: 1 }, '-=1');
      tl.to(cards[1], { y: `-=94%`, scale: 0.9, opacity: .9, duration: 1 }, '-=1');
      tl.to(cards[2], { y: `-=188%`, duration: 1 }, '-=1');
      tl.to('.section-system', { marginTop: `-=${cards[0].offsetHeight + cards[1].offsetHeight}`, duration: 1 }, '-=1')
    })
  }
})